'use strict';
// 팬 창작 연속 에피소드: RiNG에서 손님과 밴드가 함께 만드는 작은 전시.
const mainArc={
  ring_board_1:{title:'작은 게시판 ① · 빈 벽',day:7,lines:[['타키','입구 옆 벽이 좀 비어 보이네. 공연 안내를 더 붙여 둘까?'],['아논','공연 정보만 말고, 사람들이 RiNG에서 좋았던 순간을 적게 하면 어때?'],['타키','누가 그걸 써.'],['아논','해 보기 전엔 모르지! 종이랑 펜이면 되고.'],['토모리','…나는, 다른 사람들이 뭘 적는지 보고 싶어.'],['타키','토모리가 보고 싶다면… 공간부터 확인해 볼게.'],['아논','에, 토모린이 말하니까 바로? 나도 아까부터 말했거든!'],['타키','네 생각도 들었어. 통로를 안 막는지 먼저 본다는 거잖아.'],['토모리','공연이 끝난 뒤에… 말하고 싶은 게 남을 때가 있어서.'],['아논','응. 말로 바로 못 해도 적을 수 있으면 좋겠다.'],['타키','그럼 붙일 곳이랑 종이부터 알아볼게. 아직 허락은 받아야 해.']]},
  ring_board_2:{title:'작은 게시판 ② · 누가 쓸까',day:8,when:s=>s.stories.includes('ring_board_1'),lines:[['소요','붙이려면 종이가 바람에 날아가지 않게 해야겠네.'],['아논','색깔별로 나누면 예쁠 것 같지 않아?'],['타키','근데 손님이 쓸지부터 모르잖아.'],['토모리','쓰고 싶지 않은 사람은… 안 써도 돼. 그냥 읽기만 해도.'],['소요','그럼 안내에도 그렇게 적자. 부담 없이 지나갈 수 있게.'],['아논','좋아. 내가 첫 안내문 써 볼게!'],['아논','음… 너무 길면 아무도 안 읽으려나?'],['소요','무엇을 써야 한다고 정하지 말고, 쓰지 않아도 괜찮다고 적어 보자.'],['타키','펜이랑 종이는 손님이 바로 찾을 수 있는 데 둬야겠네.'],['토모리','읽고만 가는 사람도… 여기 온 거니까.'],['아논','그럼 제목은 짧게 쓰고, 그 아래에 적을게. 다 쓰면 같이 봐 줘!']]},
  ring_board_3:{title:'작은 게시판 ③ · 첫 문장',day:9,when:s=>s.stories.includes('ring_board_2'),lines:[['아논','완성! …근데 텅 비어 있으니까 아무도 먼저 못 쓰는 거 아닐까?'],['라나','그럼 네가 먼저 써.'],['아논','나? 당연히 쓰려고 했지! 뭘 쓰면 좋을지 고르는 중이었거든.'],['토모리','나도 쓸게. 오래 걸릴지도 모르지만…'],['타키','서두르지 않아도 돼. 영업 끝나고 붙여도 되고.'],['아논','그럼 나는 오늘의 첫 손님이 되어 보겠습니다!']]},
  ring_board_4:{title:'작은 게시판 ④ · 남겨진 자리',day:10,when:s=>s.stories.includes('ring_board_3'),lines:[['토모리','누가… 한 장 더 붙여 줬어.'],['소요','어제 공연 보러 온 손님일까?'],['아논','우와, 진짜네. 근데 글씨가 작아서 사진으로는 잘 안 보이겠다.'],['타키','사진 찍기 전에 쓴 사람한테 물어봐야 하는 거 아냐?'],['아논','아, 맞다. 올리기 전에 꼭 물어볼게.'],['토모리','여기에 남겨 둔 것만으로도… 기뻐.'],['아논','응. 쓰고 간 사람은 우리가 읽을 줄 알았을까?'],['소요','게시판에 붙였으니까 누군가는 읽기를 바랐을지도 모르지.'],['타키','그래도 사진까지 찍힐 거라고는 생각 못 했을 수도 있어.'],['아논','그렇겠다. 내가 예쁘게 올리고 싶다고 남의 글까지 같이 올리면 안 되지.'],['토모리','이 사람은… 어떤 노래를 들었을까.'],['소요','공연 얘기는 적혀 있지 않네.'],['토모리','응. 그래도 여기 앉아서… 잠깐 쉬었다 갔을지도 몰라.'],['아논','그런 말도 남길 수 있어서 좋다. 공연 얘기만 써야 하는 줄 알았거든.'],['타키','안내문에도 꼭 공연 얘기가 아니어도 된다고 써 놓을까?'],['아논','좋아. 종이 끝에 작게 넣으면 될까?'],['소요','처음 보는 사람도 읽게 입구 쪽에 붙이자.'],['토모리','빈 종이도 옆에 둘게. 쓰고 싶은 사람이 있으면… 바로 쓸 수 있게.']]},
  ring_board_5:{title:'작은 게시판 ⑤ · 너무 많은 종이',day:11,when:s=>s.stories.includes('ring_board_4'),lines:[['타키','게시판 앞에 사람이 모여서 주문 줄하고 겹치고 있어.','worried'],['아논','사람들이 읽어 주는 건 좋은데… 어디로 옮길까?'],['소요','출입문 쪽보다는 저 안쪽 벽이 낫지 않을까. 기다리는 사람도 앉을 수 있고.'],['라나','무대는 보여?'],['타키','저기선 안 보여. 공연 안내는 원래 자리에 둘게.'],['토모리','그러면 종이들을… 떨어뜨리지 않게 같이 옮기자.'],['아논','잠깐, 어느 종이가 어디 있었는지 모르게 되면 어떡해?'],['소요','순서대로 사진을 찍어 두고 옮기면 되겠네. 외부에 올리지는 않고.'],['타키','좋아. 손님이 돌아가고 나서 하나씩 떼자.'],['라나','이건 내가 들게.'],['타키','구기지 말고 아래를 받쳐. …응, 그렇게.']]},
  ring_board_6:{title:'작은 게시판 ⑥ · 지우고 싶은 말',day:12,when:s=>s.stories.includes('ring_board_5'),lines:[['소요','이 종이, 누가 뒤집어 놓았나 봐.','worried'],['토모리','…혹시 쓴 사람이 다시 감추고 싶었던 걸까.'],['아논','그럴 수도 있겠다. 다시 돌려 놓지는 말자.'],['타키','주인이 오면 가져갈 수 있게 그대로 둘게.'],['토모리','응. 남겨 두는 것도… 가져가는 것도 그 사람이 정하면 좋겠어.'],['아논','근데 다른 손님이 실수로 다시 뒤집으면 어떡하지?'],['타키','그 앞에 다른 종이를 붙여서 가리면, 그 종이도 읽을 수 없게 되잖아.'],['소요','안내문에 덧붙이자. 쓴 사람은 언제든 자기 종이를 가져갈 수 있다고.'],['아논','아, 펜 옆에 적어 두면 쓰기 전에도 볼 수 있겠네.'],['토모리','가져가고 나면… 빈자리가 남겠다.'],['타키','빈자리면 다음 사람이 쓸 수 있지. 굳이 바로 채울 필요도 없고.'],['토모리','응. 안 보이는 말이 있어도… 거기에 있었던 건 사라지지 않으니까.'],['아논','토모린은 그런 생각도 하는구나. 나는 뒤집힌 면이 궁금했는데.'],['토모리','나도 조금 궁금했어.'],['아논','그치? …그래도 묻지 않을게. 누가 쓴 건지도 모르니까.'],['소요','그럼 안내문을 다시 써 올게. 원래 문장은 남겨 두고, 아래에 한 줄만 더하면 되겠지?'],['타키','응. 붙이기 전에 나도 한번 볼게.']]},
  ring_board_7:{title:'작은 게시판 ⑦ · 공연이 끝난 뒤',day:13,when:s=>s.stories.includes('ring_board_6'),lines:[['아논','오늘 공연 끝나면 게시판 보는 사람 많겠다.'],['타키','그러니까 마감 전에 길부터 만들어 두자고 했잖아.'],['아논','알고 있어! 의자 이쪽으로 옮기면 되지?'],['소요','나는 펜을 확인할게. 잉크가 다 된 게 하나 있었거든.'],['라나','토모리, 아직 안 썼어?'],['토모리','응. 지금은… 조금 더 듣고 싶어.'],['라나','그럼 다 듣고 쓰면 돼.']]},
  ring_board_8:{title:'작은 게시판 ⑧ · 내일도 여기에',day:14,when:s=>s.stories.includes('ring_board_7'),lines:[['토모리','다 썼어. 짧지만… 오늘 여기에 있어서 좋았다고.'],['아논','나도! 아, 그런데 나는 좀 길게 썼다.'],['타키','게시판에 빈 자리가 없어지면 어떻게 하지?'],['소요','오래된 종이는 허락을 받고 따로 보관하자. 다음에 다시 보고 싶을 수도 있으니까.'],['라나','내일도 붙일 수 있어?'],['타키','응. 가게 여는 날은 그대로 둘게.'],['토모리','그럼 내일은… 또 다른 말이 생기겠네.'],['아논','처음에는 정말 아무도 안 쓸 줄 알았는데.'],['타키','네가 제일 먼저 종이 들고 한참 고민했잖아.'],['아논','첫 문장은 중요하거든! 덕분에 다들 쓰기 쉬웠을걸?'],['소요','아논 쨩이 먼저 붙여 둔 덕분에 어떤 곳인지 알기 쉬웠어.'],['아논','그치? 소요링은 알아준다니까.'],['라나','내 것도 있어.'],['아논','어? 라나 쨩은 언제 썼어?'],['라나','아까.'],['토모리','짧다.'],['라나','오늘 소리, 좋았어.'],['토모리','…응. 그 말, 여기 있어도 좋아.'],['타키','이제 가게 문 닫아야 해. 종이 떨어진 거 없는지만 확인하자.'],['아논','내일 와서 없어졌으면 슬플 테니까! 이쪽은 내가 볼게.'],['소요','그럼 나는 펜을 정리할게.'],['라나','토모리. 내일도 써?'],['토모리','응. 내일 듣는 말이 있으면… 또 쓰고 싶어.'],['타키','그럼 빈 종이도 남겨 두자.']] } 
};

